@Scheme.Hom.IsProjective.isProper : ∀ {X S : Scheme} {pi : X ⟶ S}, Scheme.Hom.IsProjective pi → IsProper pi
@Scheme.Hom.IsProjective.universallyClosed : ∀ {X S : Scheme} {pi : X ⟶ S},
  Scheme.Hom.IsProjective pi → UniversallyClosed pi
@Scheme.compactSpace_of_universallyClosed : ∀ {R : Type u_1} [inst : CommRing R] {X : Scheme}
  (f : X ⟶ Spec (CommRingCat.of R)) [UniversallyClosed f], CompactSpace ↥X
@Scheme.not_isProper_of_infinite_disjoint_open_cover : ∀ {R : Type u_1} [inst : CommRing R] {X : Scheme}
  (f : X ⟶ Spec (CommRingCat.of R)) {ι : Type u_2} [Infinite ι] (U : ι → Set ↥X),
  (∀ (i : ι), IsOpen (U i)) →
    (∀ (i : ι), (U i).Nonempty) → _root_.Pairwise (Function.onFun Disjoint U) → Set.univ ⊆ ⋃ i, U i → ¬IsProper f
@Scheme.not_universallyClosed_of_infinite_disjoint_open_cover : ∀ {R : Type u_1} [inst : CommRing R] {X : Scheme}
  (f : X ⟶ Spec (CommRingCat.of R)) {ι : Type u_2} [Infinite ι] (U : ι → Set ↥X),
  (∀ (i : ι), IsOpen (U i)) →
    (∀ (i : ι), (U i).Nonempty) →
      _root_.Pairwise (Function.onFun Disjoint U) → Set.univ ⊆ ⋃ i, U i → ¬UniversallyClosed f
DONE

@Finset.exists_le_maximal : ∀ {α : Type u_3} [inst : Preorder α] {a : α} (s : Finset α),
  a ∈ s → ∃ b, a ≤ b ∧ Maximal (fun x => x ∈ s) b
@Maximal : {α : Type u_3} → [LE α] → (α → Prop) → α → Prop
DONE

